#!/usr/bin/env python3
"""YAML data sampler with random, stratified, and systematic strategies."""

import random
import sys
from collections import defaultdict
from pathlib import Path

import yaml


def load_yaml(path):
    with open(path) as f:
        data = yaml.safe_load(f)
    if not isinstance(data, list):
        raise ValueError("YAML top-level must be a list of records")
    return data


def sample_random(data, n, seed=None):
    rng = random.Random(seed)
    if n >= len(data):
        return list(data)
    return rng.sample(data, n)


def sample_stratified(data, n, stratify_key, seed=None):
    rng = random.Random(seed)
    groups = defaultdict(list)
    for item in data:
        groups[item.get(stratify_key)].append(item)

    total = len(data)
    result = []
    for key, group in groups.items():
        k = max(1, round(n * len(group) / total))
        result.extend(rng.sample(group, min(k, len(group))))

    # trim or pad to exactly n
    if len(result) > n:
        result = rng.sample(result, n)
    while len(result) < n and len(result) < len(data):
        remaining = [x for x in data if x not in result]
        if not remaining:
            break
        result.append(rng.choice(remaining))
    return result


def sample_systematic(data, n, start=None, seed=None):
    rng = random.Random(seed)
    if n >= len(data):
        return list(data)
    step = len(data) / n
    if start is None:
        start = rng.random() * step
    return [data[int(start + i * step) % len(data)] for i in range(n)]


def dump_yaml(records, path=None):
    out = yaml.dump(records, default_flow_style=False, allow_unicode=True, sort_keys=False)
    if path:
        Path(path).write_text(out)
    else:
        print(out)


def main():
    import argparse

    parser = argparse.ArgumentParser(description="Sample YAML data using different strategies")
    parser.add_argument("input", help="Input YAML file")
    parser.add_argument("-n", "--count", type=int, required=True, help="Sample size")
    parser.add_argument("-s", "--strategy", choices=["random", "stratified", "systematic"], default="random")
    parser.add_argument("-k", "--key", help="Stratification key (required for stratified)")
    parser.add_argument("--seed", type=int, help="Random seed")
    parser.add_argument("-o", "--output", help="Output file (default: stdout)")
    args = parser.parse_args()

    if args.strategy == "stratified" and not args.key:
        parser.error("--key is required for stratified sampling")

    data = load_yaml(args.input)

    match args.strategy:
        case "random":
            result = sample_random(data, args.count, seed=args.seed)
        case "stratified":
            result = sample_stratified(data, args.count, args.key, seed=args.seed)
        case "systematic":
            result = sample_systematic(data, args.count, seed=args.seed)

    dump_yaml(result, args.output)
    print(f"Sampled {len(result)} / {len(data)} records ({args.strategy})", file=sys.stderr)


if __name__ == "__main__":
    main()
